// External score-localization control; retains the in-tree strict dot helper.
#include "gemma4_attention.hip"
template<int DIM>
__global__ void diagnostic_strict_scores_kernel(const uint16_t* query, const uint16_t* key,
    const uint8_t* mask, float* out, int64_t tokens, int64_t heads, int64_t kv_heads, int64_t keys) {
  const int row=blockIdx.z, head=blockIdx.y, pos=blockIdx.x;
  const int lane=threadIdx.x;
  const int64_t idx=(static_cast<int64_t>(row)*heads+head)*keys+pos;
  if (!mask[static_cast<int64_t>(row)*keys+pos]) {if(lane==0)out[idx]=-INFINITY;return;}
  __shared__ float q[DIM];
  for(int d=lane; d<DIM; d+=32) q[d]=gemma4_attn_bf16_bits_to_float(query[(static_cast<int64_t>(row)*heads+head)*DIM+d]);
  __syncthreads();
  const uint16_t* k=key+(static_cast<int64_t>(pos)*kv_heads+head/(heads/kv_heads))*DIM;
  const float score=gemma4_warp_key_logit<uint16_t,DIM/32>(q,k,lane);
  if(lane==0) out[idx]=score;
}
__global__ void diagnostic_global_stats_kernel(const float* scores, float* stats,
 int64_t keys, float scale) {
  __shared__ float partial[256];
  const int64_t row = blockIdx.x;
  float maximum = -INFINITY;
  for (int64_t key = threadIdx.x; key < keys; key += 256) {
    maximum = fmaxf(maximum, scores[row * keys + key] * scale);
  }
  const float global_max = gemma4_attn_block_max(partial, maximum);
  float sum = 0.0f;
  for (int64_t key = threadIdx.x; key < keys; key += 256) {
    sum += expf(scores[row * keys + key] * scale - global_max);
  }
  const float denominator = gemma4_attn_block_sum(partial, sum);
  if (threadIdx.x == 0) { stats[row * 2] = global_max; stats[row * 2 + 1] = denominator; }
}
extern "C" int diagnostic_global_stats(const float* scores, float* stats,
 int64_t tokens, int64_t heads, int64_t keys, float scale) {
  hipLaunchKernelGGL(diagnostic_global_stats_kernel, dim3(tokens * heads), dim3(256),
                    0, 0, scores, stats, keys, scale);
  return hipGetLastError();
}

__global__ void diagnostic_weights_kernel(float* scores, const float* stats,
 int64_t elements, int64_t keys, float scale) {
  const int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
  if (index < elements) {
    scores[index] = expf(scores[index] * scale - stats[(index / keys) * 2]);
  }
}
__global__ void diagnostic_scalar_pv_kernel(const float* weights, const float* stats,
 const uint16_t* value, uint16_t* out, int64_t heads, int64_t kv_heads,
 int64_t dim, int64_t keys) {
  const int64_t row = blockIdx.x;
  const int64_t head = row % heads;
  const int64_t kv_head = head / (heads / kv_heads);
  extern __shared__ float weights_shared[];
  for (int64_t key = threadIdx.x; key < keys; key += blockDim.x) {
    weights_shared[key] = weights[row * keys + key];
  }
  __syncthreads();
  if (dim == 512) {
    gemma4_decode_pass3<2,4>(weights_shared, value + kv_head * dim, out + row * dim,
       kv_heads * dim, dim, keys, stats[row * 2 + 1], blockDim.x, threadIdx.x);
  } else {
    gemma4_decode_pass3<1,4>(weights_shared, value + kv_head * dim, out + row * dim,
       kv_heads * dim, dim, keys, stats[row * 2 + 1], blockDim.x, threadIdx.x);
  }
}
extern "C" int diagnostic_scalar_pv(float* scores, const float* stats,
 const uint16_t* value, uint16_t* out, int64_t tokens, int64_t heads,
 int64_t kv_heads, int64_t dim, int64_t keys, float scale) {
  if (keys * sizeof(float) > 64 * 1024) return hipErrorInvalidValue;
  const int64_t elements = tokens * heads * keys;
  hipLaunchKernelGGL(diagnostic_weights_kernel, dim3((elements+255)/256),dim3(256),
                    0,0,scores,stats,elements,keys,scale);
  int rc = hipGetLastError(); if (rc) return rc;
  hipLaunchKernelGGL(diagnostic_scalar_pv_kernel, dim3(tokens * heads),dim3(256),
       keys*sizeof(float),0,scores,stats,value,out,heads,kv_heads,dim,keys);
  return hipGetLastError();
}

extern "C" int diagnostic_strict_scores(const uint16_t* query,const uint16_t* key,
 const uint8_t* mask,float* out,int64_t tokens,int64_t heads,int64_t kv_heads,int64_t dim,int64_t keys) {
 dim3 grid(keys,heads,tokens);
 if(dim==512)hipLaunchKernelGGL((diagnostic_strict_scores_kernel<512>),grid,dim3(32),0,0,query,key,mask,out,tokens,heads,kv_heads,keys);
 else if(dim==256)hipLaunchKernelGGL((diagnostic_strict_scores_kernel<256>),grid,dim3(32),0,0,query,key,mask,out,tokens,heads,kv_heads,keys);
 else return hipErrorInvalidValue;
 return hipGetLastError();
}
